package com.utec.tropelcare.controller; import com.utec.tropelcare.dto.*; import com.utec.tropelcare.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/v1/signals") public class SignalController{private final SignalService s;private final CareService c;private final NotificationService n;public SignalController(SignalService s,CareService c,NotificationService n){this.s=s;this.c=c;this.n=n;}@PostMapping public ResponseEntity<SignalDto> create(@Valid @RequestBody SignalRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping public PageResponse<SignalDto> search(@RequestParam(required=false) String signalType,@RequestParam(required=false) String severity,@RequestParam(required=false) String status,@RequestParam(required=false) Long tropelId,@RequestParam(required=false) Long guardianId,@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return s.search(signalType,severity,status,tropelId,guardianId,from,to,page,size);}@GetMapping("/{id}") public SignalDto get(@PathVariable Long id){return s.get(id);}@GetMapping("/{id}/care-response") public CareResponseDto care(@PathVariable Long id){return c.getBySignal(id);}@GetMapping("/{id}/notifications") public List<NotificationLogDto> notifications(@PathVariable Long id){return n.list(id);}}
